T=/dd/SYS/termcapecho "@@CASE@@compress-round-trip"/dd/CMDS/compress -c < $T > /dd/tmp/z.Z/dd/CMDS/compress -dc < /dd/tmp/z.Z > /dd/tmp/z.out/dd/CMDS/md5 /dd/tmp/z.outecho "@@CASE@@compress-really-compresses"/dd/CMDS/wc -c /dd/tmp/z.Zecho "@@CASE@@gzip-round-trip"/dd/CMDS/gzip -c < $T > /dd/tmp/g.gz/dd/CMDS/gzip -dc < /dd/tmp/g.gz > /dd/tmp/g.out/dd/CMDS/md5 /dd/tmp/g.outecho "@@CASE@@gzip-really-compresses"/dd/CMDS/wc -c /dd/tmp/g.gzecho "@@CASE@@gzip-reads-what-compress-wrote"/dd/CMDS/gzip -dc < /dd/tmp/z.Z > /dd/tmp/zg.out/dd/CMDS/md5 /dd/tmp/zg.outecho "@@CASE@@tar-round-trip"/dd/CMDS/cp $T /dd/tmp/tarme.txt/dd/CMDS/tar cf /dd/tmp/t.tar /dd/tmp/tarme.txt/dd/CMDS/rm /dd/tmp/tarme.txt/dd/CMDS/tar xf /dd/tmp/t.tar/dd/CMDS/md5 /dd/tmp/tarme.txtecho "@@CASE@@tar-lists-what-it-stored"/dd/CMDS/tar tvf /dd/tmp/t.tarecho "@@CASE@@zoo-adds-and-lists"/dd/CMDS/zoo a /dd/tmp/a.zoo $T/dd/CMDS/zoo l /dd/tmp/a.zooecho "@@CASE@@booz-reads-a-zoo"/dd/CMDS/booz -l /dd/tmp/a.zooecho "@@CASE@@zip-cannot-write-its-archive"/dd/CMDS/zip /dd/tmp/a.zip $Techo "@@CASE@@lha-round-trip"/dd/CMDS/cp $T /dd/tmp/lhame.txt/dd/CMDS/lha a /dd/tmp/a.lzh /dd/tmp/lhame.txt/dd/CMDS/rm /dd/tmp/lhame.txt/dd/CMDS/lha x /dd/tmp/a.lzh/dd/CMDS/md5 /dd/tmp/lhame.txtecho "@@CASE@@lha-lists-with-a-ratio"/dd/CMDS/lha l /dd/tmp/a.lzhecho "@@CASE@@lharc-makes-an-archive-lha-can-read"/dd/CMDS/lharc a /dd/tmp/b.lzh $T/dd/CMDS/lha l /dd/tmp/b.lzhecho "@@CASE@@ar-adds-and-lists"/dd/CMDS/ar -u tmp/a.ar SYS/termcap/dd/CMDS/ar -t tmp/a.arecho "@@CASE@@ar-refuses-an-absolute-path"/dd/CMDS/ar -u tmp/b.ar /dd/SYS/termcapecho "@@CASE@@ar2-reads-what-ar-wrote"/dd/CMDS/ar2 -t tmp/a.arecho "@@CASE@@marc-is-a-merger-not-an-archiver"/dd/CMDS/marcecho "@@CASE@@arc-cannot-write-its-archive"/dd/CMDS/REBUILT/arc -a tmp/y.arc SYS/termcapecho "@@CASE@@shar-wraps-a-file-as-a-script"/dd/CMDS/shar /dd/SYS/motd > /dd/tmp/a.shar/dd/CMDS/head -n 12 /dd/tmp/a.sharecho "@@CASE@@zoo-2.1-reads-what-zoo-wrote"/dd/CMDS/REBUILT/zoo_2.1 l /dd/tmp/a.zooecho "@@CASE@@compress_4.0-agrees-with-compress"/dd/CMDS/REBUILT/compress_4.0 -dc < /dd/tmp/z.Z > /dd/tmp/c4.out/dd/CMDS/md5 /dd/tmp/c4.outecho "@@CASE@@the-four-gzip-builds-all-read-the-same-file"/dd/CMDS/REBUILT/gzip68k_nocsl -dc < /dd/tmp/g.gz > /dd/tmp/g1.out/dd/CMDS/REBUILT/gzip020_nocsl -dc < /dd/tmp/g.gz > /dd/tmp/g2.out/dd/CMDS/md5 /dd/tmp/g1.out /dd/tmp/g2.outecho "@@CASE@@gtar-reads-what-tar-wrote"/dd/CMDS/REBUILT/gtar tf /dd/tmp/t.tarecho "@@CASE@@funzip-has-nothing-to-read"/dd/CMDS/funzip < /dd/tmp/a.zipecho "@@CASE@@end"